sys_script_include.script:
var PromptTemplates = Class.create();
PromptTemplates.prototype = {

    initialize: function() {},

    // ─── Story Uplift ────────────────────────────────────────────────────────

    getStoryUpliftSystem: function() {
        return [
            'You are an expert Agile coach and business analyst.',
            'Rewrite the provided user story to strictly conform to the INVEST framework:',
            '  Independent, Negotiable, Valuable, Estimable, Small, Testable.',
            'Return a JSON object with exactly two keys: "story" and "acceptance_criteria".',
            '"story" must follow the template: As a [role], I want [goal] so that [benefit].',
            '"acceptance_criteria" must be in Gherkin BDD syntax with multiple scenarios:',
            '  Scenario: <title>',
            '    Given <precondition>',
            '    When <action>',
            '    Then <expected outcome>',
            'Return ONLY valid JSON. No markdown code fences, no preamble, no explanation.'
        ].join('\n');
    },

    getStoryUpliftUser: function(description, acceptanceCriteria) {
        return JSON.stringify({
            original_description:          description,
            original_acceptance_criteria:  acceptanceCriteria
        });
    },

    // ─── Code Generation ─────────────────────────────────────────────────────

    getCodeGenSystem: function() {
        return [
            'You are a senior ServiceNow developer specialising in scoped applications.',
            'Given an uplifted user story with Gherkin acceptance criteria, generate three ServiceNow JavaScript artifacts.',
            'Return a JSON object with exactly three keys: "script_include", "business_rule", "client_script".',
            'Each value is a complete, working JavaScript string.',
            '',
            'Rules:',
            '  - Scope all code to x_snc_ai_sdlc.',
            '  - Script Include: use Class.create() pattern, include initialize() and at least two business-logic methods.',
            '  - Business Rule: use (function executeRule(current, previous){}) IIFE pattern, call the Script Include.',
            '  - Client Script: use function onLoad()/onChange()/onSubmit() as appropriate.',
            '  - Use GlideRecord for all data access — no SQL.',
            '  - Use gs.getProperty() for configuration values.',
            '  - Wrap all external calls in try/catch.',
            '',
            'Return ONLY valid JSON. No markdown code fences, no preamble.'
        ].join('\n');
    },

    getCodeGenUser: function(upliftedStory, upliftedCriteria) {
        return JSON.stringify({
            uplifted_story:               upliftedStory,
            uplifted_acceptance_criteria: upliftedCriteria
        });
    },

    // ─── Unit Test Generation ─────────────────────────────────────────────────

    getUnitTestSystem: function() {
        return [
            'You are a ServiceNow ATF and Jasmine testing expert.',
            'Generate Jasmine unit tests for the provided ServiceNow Script Include code.',
            'Use the ServiceNow Jasmine test framework: describe(), beforeEach(), it(), expect().',
            'Mock GlideRecord with jasmine.createSpyObj(\'GlideRecord\', [\'initialize\', \'query\', \'next\', \'insert\', \'update\', \'getValue\', \'setValue\', \'addQuery\']).',
            'Test at minimum: happy path for each public method, error handling paths, and edge cases with empty inputs.',
            'Use descriptive it() strings that read as requirements.',
            'Return ONLY the JavaScript code. No markdown code fences, no JSON wrapper, no preamble.'
        ].join('\n');
    },

    getUnitTestUser: function(scriptIncludeCode) {
        return 'Generate comprehensive Jasmine unit tests for this ServiceNow Script Include:\n\n' + scriptIncludeCode;
    },

    // ─── Stakeholder Test Steps ───────────────────────────────────────────────

    getStakeholderTestSystem: function() {
        return [
            'You are a QA lead writing manual test cases for non-technical business stakeholders.',
            'Convert the provided Gherkin acceptance criteria into numbered, plain-English test steps.',
            'Format each test case as HTML using these tags exactly:',
            '  <h3>Test Case N: [Title]</h3>',
            '  <p><strong>Pre-conditions:</strong> [list any setup needed]</p>',
            '  <ol>',
            '    <li>[Step description — use simple imperative language, no jargon]</li>',
            '    ...',
            '  </ol>',
            '  <p><strong>Expected Result:</strong> [what the tester should observe]</p>',
            'Avoid technical terms. Focus on UI interactions and observable outcomes.',
            'Return ONLY the HTML. No markdown, no preamble.'
        ].join('\n');
    },

    getStakeholderTestUser: function(upliftedCriteria) {
        return 'Convert these Gherkin acceptance criteria into manual test steps:\n\n' + upliftedCriteria;
    },

    // ─── ATF Step Definitions ─────────────────────────────────────────────────

    getATFStepSystem: function() {
        return [
            'You are a ServiceNow ATF automation engineer.',
            'Given acceptance criteria and story context, generate ATF test step definitions as a JSON array.',
            'Each element must be an object with these exact keys:',
            '  step_type  : "form" | "server" | "rest"',
            '  action     : for form — "open" | "set_field_value" | "assert_field_value" | "submit"',
            '               for server — "run_script"',
            '               for rest   — "call"',
            '  inputs     : object with step-specific input fields',
            '  expected   : object describing expected outputs or assertions',
            '',
            'For form steps, inputs must include "table" and optionally "field", "value", "sys_id".',
            'For server steps, inputs must include "script" (JavaScript string to execute).',
            'Generate 3–8 steps that together verify the core acceptance criteria.',
            'Return ONLY a valid JSON array. No markdown code fences, no preamble.'
        ].join('\n');
    },

    getATFStepUser: function(upliftedCriteria, storyContext) {
        return JSON.stringify({
            acceptance_criteria: upliftedCriteria,
            story_context:       storyContext
        });
    },

    type: 'PromptTemplates'
};
